import { useState, useEffect, useRef, useCallback, type ReactNode } from 'react';
import { ReactFlowProvider, Handle, Position, type NodeProps } from '@xyflow/react';
import { Workflow, LayoutDashboard, Database, Plug, BrainCircuit, History, Settings2, Plus, ArrowUpRight, ArrowRight, ChevronRight, ChevronDown, Check, X, Play, Save, Search, Upload, FileText, FolderOpen, Globe2, Terminal, ShieldCheck, Shield, LockKeyhole, Sparkles, SlidersHorizontal, CircleHelp, MoreHorizontal, Trash2, Copy, Download, Clock3, CheckCircle2, Circle, AlertCircle, LoaderCircle, Network, GitBranch, WandSparkles, ScanText, PanelRightClose, PanelRightOpen, MousePointer2, Move, Bolt, Server, Cable, Send, Filter, BookOpen, Code2, Menu, ExternalLink, Monitor, RefreshCw, Inbox } from 'lucide-react';

import WorkflowStudio from './WorkflowStudio';
import AgentsPage from './AgentsPage';
import VideoWorkflow from './VideoWorkflow';
import { cleanWorkflow, cloneWorkflow, workflowIssues, workflowKey } from '../shared/workflow.mjs';

type Item = Record<string, any>;
function lastWorkflowId(){try{return localStorage.getItem('agentflux:last-workflow');}catch{return null;}}
type View = 'overview'|'studio'|'data'|'connectors'|'models'|'runs'|'settings'|'templates'|'agents';
const nav: {id:View;label:string;icon:any}[]=[{id:'agents',label:"Agents",icon:BrainCircuit},{id:'templates',label:"Templates",icon:BookOpen},{id:'overview',label:"Overview",icon:LayoutDashboard},{id:'studio',label:"Workflow editor",icon:Workflow},{id:'data',label:"Knowledge base",icon:Database},{id:'connectors',label:"Connections",icon:Plug},{id:'models',label:"Models",icon:BrainCircuit},{id:'runs',label:"Runs",icon:History}];
const kinds:Record<string,Item>={
 agent:{label:'Agent',description:"Work with tasks, knowledge and skills",icon:Sparkles,color:'purple',default:{agentId:'',prompt:'',skillIds:[],useMemory:true},tag:'AGENT'},
 trigger:{label:'Start',description:"Trigger a workflow",icon:Play,color:'green',default:{},tag:'START'},
 source:{label:"Data source",description:"Files, APIs and programs",icon:FolderOpen,color:'blue',default:{connectorId:'inbox'},tag:"DATA SOURCE"},
 redact:{label:"Redact",description:"Replace sensitive information",icon:ShieldCheck,color:'mint',default:{},tag:"REDACTION"},
 transform:{label:"Transform",description:"Clean data and map fields",icon:SlidersHorizontal,color:'orange',default:{operation:'clean'},tag:"PROCESSING"},
 condition:{label:"Condition",description:"Choose the next step",icon:GitBranch,color:'orange',default:{field:'content',operator:'contains',value:''},tag:"LOGIC"},
 model:{label:"AI model",description:"Process data with your model",icon:BrainCircuit,color:'purple',default:{prompt:"Write an accurate summary with sources."},tag:"AI MODEL"},
 store:{label:"Save",description:"Save to the knowledge base",icon:Database,color:'green',default:{},tag:"OUTPUT"},
 output:{label:"Output",description:"View results in the run",icon:FileText,color:'blue',default:{},tag:"OUTPUT"}
};
const connectorTypes:Record<string,Item>={folder:{label:"Local folder",icon:FolderOpen,color:'blue',detail:"Import files automatically"},http:{label:'HTTP / REST API',icon:Globe2,color:'purple',detail:"Internal and external services"},program:{label:"Local program",icon:Terminal,color:'orange',detail:"Connect existing tools"},text:{label:'Text & JSON',icon:Code2,color:'mint',detail:"Paste data directly"}};
async function api(path:string,options:RequestInit={}) {const response=await fetch('/api'+path,{...options,headers:options.body instanceof FormData?options.headers:{'Content-Type':'application/json',...options.headers}});const text=await response.text();let data:any;try{data=text?JSON.parse(text):{};}catch{throw new Error("The server returned an unreadable response. Reload the page.");}if(!response.ok)throw new Error(data.error||"Connection failed.");return data;}
const post=(path:string,body:unknown={})=>api(path,{method:'POST',body:JSON.stringify(body)});
const formatDate=(date?:string)=>date?new Intl.DateTimeFormat("en-GB",{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(date)):"Not yet";
const duration=(ms:number)=>ms<1000?`${ms || 0} ms`:`${(ms/1000).toFixed(1)} s`;
const cx=(...values:any[])=>values.filter(Boolean).join(' ');
const IconBox=({icon:Icon,color='green',size=''}:any)=><span className={`icon-box ${color} ${size}`}><Icon size={size==='large'?25:19} strokeWidth={1.7}/></span>;
function Button({children,icon:Icon,onClick,variant='',disabled=false,className='',...props}:any){return <button className={cx('button',variant,className)} onClick={onClick} disabled={disabled} {...props}>{Icon&&<Icon size={16}/>} {children}</button>;}
function Field({label,hint,children}:any){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>;}
function Toggle({checked,onChange,label,description}:any){return <label className="toggle-row"><span><strong>{label}</strong>{description&&<small>{description}</small>}</span><input type="checkbox" checked={!!checked} onChange={e=>onChange(e.target.checked)}/><span className="switch"/></label>;}
function Empty({icon:Icon,title,description,children}:any){return <div className="empty-state"><span className="empty-icon"><Icon size={30} strokeWidth={1.4}/></span><h3>{title}</h3><p>{description}</p>{children}</div>;}
function Modal({title,description,onClose,children,wide=false}:any){const ref=useRef<HTMLDivElement>(null);useEffect(()=>{const previous=document.activeElement as HTMLElement;const el=ref.current;el?.querySelector<HTMLElement>('input,button,textarea,select')?.focus();const onKey=(e:KeyboardEvent)=>{if(e.key==='Escape')onClose();if(e.key==='Tab'){const list=el?.querySelectorAll<HTMLElement>('button:not(:disabled),input,textarea,select,[tabindex="0"]');if(!list?.length)return;const first=list[0],last=list[list.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};document.addEventListener('keydown',onKey);return()=>{document.removeEventListener('keydown',onKey);previous?.focus();};},[]);return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><div ref={ref} role="dialog" aria-modal="true" aria-label={title} className={cx('modal',wide&&'wide')}><div className="modal-heading"><div><h2>{title}</h2>{description&&<p>{description}</p>}</div><button className="icon-button" onClick={onClose} aria-label="Close"><X size={20}/></button></div>{children}</div></div>;}

function restoreDraft(w:Item|null){try{const id=w?.id||localStorage.getItem('agentflux:last-workflow');const raw=id&&localStorage.getItem('agentflux:draft:'+id);return raw?JSON.parse(raw):w;}catch{return w;}}

function initialWorkflow(workflows:Item[]){try{const id=lastWorkflowId();const draft=id&&localStorage.getItem('agentflux:draft:'+id);if(draft){const value=JSON.parse(draft);if(value.id===id&&Array.isArray(value.nodes)&&Array.isArray(value.edges))return value;}return workflows.find(w=>w.id===id)||workflows.find(w=>w.id==='document-flow')||workflows[0]||null;}catch{return workflows[0]||null;}}

export default function App(){
 const [data,setData]=useState<Item|null>(null);const [view,setView]=useState<View>(()=>(location.hash.slice(1) as View)||'overview');const [workflow,setWorkflow]=useState<Item|null>(null);const [toast,setToast]=useState<Item|null>(null);const [busy,setBusy]=useState('');const [modal,setModal]=useState<Item|null>(null);const [mobileNav,setMobileNav]=useState(false);const [loadError,setLoadError]=useState('');const [connected,setConnected]=useState(true);const [selectedRun,setSelectedRun]=useState<Item|null>(null);
 const notify=useCallback((message:string,error=false)=>setToast({message,error,id:Date.now()}),[]);
 const refresh=useCallback(async()=>{const next=await api('/bootstrap');setData(next);setWorkflow(current=>current||initialWorkflow(next.workflows));return next;},[]);
 useEffect(()=>{refresh().catch(e=>setLoadError(e.message));const events=new EventSource('/api/events');events.onopen=()=>{setConnected(true);refresh().catch(()=>{});};events.onerror=()=>setConnected(false);events.onmessage=e=>{const event=JSON.parse(e.data);if(event.type==='run'){setData(current=>current?{...current,runs:[event.value,...current.runs.filter((r:Item)=>r.id!==event.value.id)].slice(0,30)}:current);setSelectedRun(current=>current?.id===event.value.id?event.value:current);if(event.value.status!=='running')refresh().catch(()=>{});}if(['records','agent','skill','learning','agents','skills','learnings'].includes(event.type))refresh().catch(()=>{});};return()=>events.close();},[refresh]);
 useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(null),5000);return()=>clearTimeout(t);}},[toast]);
 const go=(next:View)=>{setView(next);location.hash=next;setMobileNav(false);};
 useEffect(()=>{const h=()=>setView((location.hash.slice(1) as View)||'overview');window.addEventListener('hashchange',h);const key=(e:KeyboardEvent)=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();setModal({type:'search'});}};window.addEventListener('keydown',key);return()=>{window.removeEventListener('hashchange',h);window.removeEventListener('keydown',key);};},[]);
 const act=async(label:string,fn:()=>Promise<any>)=>{setBusy(label);try{return await fn();}catch(e:any){notify(e.message,true);}finally{setBusy('');}};
 const savedWorkflow=data?.workflows.find((w:Item)=>w.id===workflow?.id);const dirty=!!workflow&&workflowKey(workflow)!==workflowKey(savedWorkflow);
 useEffect(()=>{if(!workflow)return;try{localStorage.setItem('agentflux:last-workflow',workflow.id);if(dirty)localStorage.setItem('agentflux:draft:'+workflow.id,JSON.stringify(cleanWorkflow(workflow)));else localStorage.removeItem('agentflux:draft:'+workflow.id);}catch{}},[workflow,dirty]);
 useEffect(()=>{if(!dirty)return;const guard=(event:BeforeUnloadEvent)=>{event.preventDefault();event.returnValue='';};window.addEventListener('beforeunload',guard);return()=>window.removeEventListener('beforeunload',guard);},[dirty]);
 const save=async(w=workflow)=>{if(!w)throw new Error("No workflow selected.");const before=workflowKey(workflow);const saved=await post('/workflows',cleanWorkflow(w));setWorkflow(current=>current?.id===saved.id&&workflowKey(current)===before?saved:current);await refresh();return saved;};
 const run=()=>act('run',async()=>{if(!workflow)throw new Error("Select a workflow first.");const issues=workflowIssues(workflow,data||{});if(issues.length)throw new Error(issues[0].message);const saved=await save();const r=await post(`/workflows/${saved.id}/run`);setSelectedRun(r);notify("Workflow started. Steps will appear live.");});
 const openWorkflow=(w:Item)=>{if(!w){go('templates');return;}setWorkflow(restoreDraft(structuredClone(w)));go('studio');};
 const newWorkflow=()=>{const w={id:crypto.randomUUID(),name:"My new workflow",description:'',category:"Custom workflow",nodes:[{id:'start',type:'flux',position:{x:100,y:150},data:{kind:'trigger',label:"Start workflow",config:{}}}],edges:[],policy:{allowCloud:false,redactCloud:true},schedule:{enabled:false,intervalMinutes:60}};setWorkflow(w);go('studio');};
 const upload=async(files:FileList|File[])=>act('upload',async()=>{const form=new FormData();Array.from(files).forEach(file=>form.append('files',file));const result=await api('/uploads',{method:'POST',body:form});notify(`${result.count} records imported and saved.`);await refresh();window.dispatchEvent(new Event('records-changed'));});
 useEffect(()=>{const key=(event:KeyboardEvent)=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'&&workflow){event.preventDefault();void act('save',async()=>{await save();notify("Workflow saved.");});}};window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key);},[workflow]);
 const duplicateWorkflow=()=>{if(!workflow)return;setWorkflow(cloneWorkflow(workflow,workflow.name+" (Copy)"));setModal(null);go('studio');};
 const useTemplate=(template:Item)=>{const next=cloneWorkflow(template.workflow,template.name);if(data?.providers.length===1)next.nodes.forEach((n:Item)=>{if(n.data.kind==='model')n.data.config.providerId=data.providers[0].id;});setWorkflow(next);go('studio');};
 const importWorkflow=(file:File)=>act('import-workflow',async()=>{if(file.size>2*1024*1024)throw new Error("Workflow files must be no larger than 2 MB.");const parsed=JSON.parse(await file.text());const raw=parsed.workflow||parsed;if(!Array.isArray(raw.nodes)||!Array.isArray(raw.edges)||typeof raw.name!=='string')throw new Error("This file does not contain a workflow.");const imported=cloneWorkflow(raw,raw.name+' (Import)');const saved=await post('/workflows',imported);await refresh();openWorkflow(saved);notify("Workflow imported. Assign sources and models in the editor.");});
 if(!data)return <div className="boot-screen"><Logo/><h2>{loadError?"AgentFlux is unavailable":"Starting AgentFlux"}</h2><p>{loadError||"Connecting to your local AgentFlux instance."}</p>{loadError&&<Button onClick={()=>location.reload()} icon={RefreshCw}>Reconnect</Button>}</div>;
 const currentRun=data.runs.find((r:Item)=>r.workflowId===workflow?.id);const activeRun=currentRun?.status==='running';
 return <div className="app-shell">
  <aside className={cx('sidebar',mobileNav&&'mobile-open')}>
   <a className="brand" aria-label="AgentFlux overview" href="#overview" onClick={()=>go('overview')}><Logo/><span>AgentFlux<span className="brand-dot">.</span></span></a>
   <div className="workspace-switch"><span className="workspace-avatar">A</span><span><strong>My AgentFlux</strong><small>Local instance</small></span><ChevronDown size={15}/></div>
   <div className="nav-caption">PLATFORM</div>
   <nav>{nav.map(({id,label,icon:Icon})=><button key={id} aria-label={label} title={label} className={cx('nav-item',view===id&&'active')} onClick={()=>go(id)}><Icon size={19} strokeWidth={1.7}/><span>{label}</span>{id==='studio'&&<span className="nav-count">{data.workflows.length}</span>}{view===id&&<span className="nav-active-dot"/>}</button>)}</nav>
   <div className="sidebar-note"><div className="orbit-symbol"><Network size={29} strokeWidth={1.1}/></div><strong>Files, APIs and<br/>local programs</strong><p>Data sources for your workflows.</p><button onClick={()=>go('connectors')}>Add connection <ArrowUpRight size={15}/></button></div>
   <div className="sidebar-bottom"><button aria-label="Settings" title="Settings" className={cx('nav-item',view==='settings'&&'active')} onClick={()=>go('settings')}><Settings2 size={18}/>Settings</button><button className="nav-item" aria-label="Quick start" title="Quick start" onClick={()=>setModal({type:'help'})}><CircleHelp size={18}/>Quick start</button><div className="local-status"><span className="status-dot"/><span>{connected?"Connected locally":"Connection lost"}<small>AgentFlux · v0.2.0</small></span><LockKeyhole size={14}/></div></div>
  </aside>
  <main className="main-shell">
   <header className="topbar"><div className="breadcrumb"><button className="icon-button mobile-menu" onClick={()=>setMobileNav(!mobileNav)} aria-label="Navigation"><Menu size={20}/></button><span>AgentFlux</span><ChevronRight size={14}/><strong>{view==='settings'?"Settings":nav.find(n=>n.id===view)?.label||"Overview"}</strong></div><div className="topbar-right"><button className="search-trigger" aria-label="Search" onClick={()=>setModal({type:'search'})}><Search size={15}/><span>Search</span><kbd>Ctrl K</kbd></button><span className="local-pill"><span className="status-dot"/>Self-hosted</span><span className="user-avatar">YOU</span></div></header>
   {view==='overview'&&<Overview data={data} openWorkflow={openWorkflow} go={go} newWorkflow={()=>go('templates')} assistant={()=>setModal({type:'assistant'})}/>}
   {view==='templates'&&<TemplatePage data={data} choose={useTemplate} create={newWorkflow} importFile={importWorkflow} assistant={()=>setModal({type:'assistant'})} act={act} refresh={refresh}/>}
   {view==='agents'&&<AgentsPage data={data} notify={notify} refresh={refresh} onVideo={()=>setModal({type:'video'})} onOpenWorkflow={async(id:string)=>{const next=await refresh();openWorkflow(next.workflows.find((w:Item)=>w.id===id));}}/>}
   {!connected&&<div className="connection-banner" role="status">Server connection lost. Changes remain saved as a draft in this browser.</div>}
   {view==='studio'&&<div className="studio-page"><div className="studio-heading"><div className="workflow-picker"><IconBox icon={Workflow} color="green"/><div><select aria-label="Select workflow" value={workflow?.id||''} onChange={e=>openWorkflow(data.workflows.find((w:Item)=>w.id===e.target.value))}>{!data.workflows.find((w:Item)=>w.id===workflow?.id)&&workflow&&<option value={workflow.id}>{workflow.name}</option>}{data.workflows.map((w:Item)=><option key={w.id} value={w.id}>{w.name}</option>)}</select><p>{workflow?.description||"Add, connect and configure steps."}</p></div></div><div className="heading-actions"><button className="icon-button" title="Workflow settings" onClick={()=>setModal({type:'workflow'})}><Settings2 size={19}/></button><button className="icon-button" title="Templates and new workflows" onClick={()=>go('templates')}><Plus size={19}/></button><Button icon={Save} disabled={!!busy} onClick={()=>act('save',async()=>{await save();notify("Workflow saved.");})}>Save</Button>{activeRun&&<Button variant="danger" onClick={()=>act('cancel',async()=>{await post('/runs/'+currentRun.id+'/cancel');notify("Cancellation requested. Completed steps are kept.");})}>Cancel</Button>}<Button variant="primary" icon={activeRun?LoaderCircle:Play} disabled={!!busy||activeRun||!workflow} onClick={run}>{activeRun?"Running …":"Start workflow"}</Button></div></div>
    <div className="studio-subbar"><div className="studio-tabs"><span className="selected"><Workflow size={14}/>Editor</span><button onClick={()=>{if(currentRun)setSelectedRun(currentRun);else notify("Start the workflow to see its results.");}}><History size={14}/>Last run{currentRun&&<span className={cx('tiny-dot',currentRun.status)}/>}</button></div><div className="canvas-meta"><span><Shield size={13}/>{workflow?.policy?.allowCloud?"External transfers allowed":"External transfers blocked"}</span><span>{workflow?.nodes?.length||0} steps</span><button onClick={()=>setModal({type:'assistant'})}><Sparkles size={14}/>Draft workflow</button></div></div>
    {workflow?<ReactFlowProvider key={workflow.id}><WorkflowStudio workflow={workflow} onChange={setWorkflow} data={data} currentRun={dirty?null:currentRun} kinds={kinds} nodeTypes={nodeTypes} NodeFields={NodeFields}/></ReactFlowProvider>:<Empty icon={Workflow} title="Create workflow" description="Build a workflow from reusable steps."><Button onClick={newWorkflow} icon={Plus}>Create workflow</Button></Empty>}
    <div className="studio-footer"><span><MousePointer2 size={13}/>Drag and connect steps</span><span><Move size={13}/>Drag an empty area to pan</span><span className="footer-right">{dirty?"Draft saved in this browser":workflow?.updatedAt?`Saved ${formatDate(workflow.updatedAt)}`:"Not saved yet"}<span className="status-dot"/></span></div>
   </div>}
   {view==='data'&&<DataPage data={data} upload={upload} busy={busy} act={act} notify={notify} refresh={refresh}/>}
   {view==='connectors'&&<ConnectorsPage data={data} edit={(item?:Item)=>setModal({type:'connector',item})} act={act} refresh={refresh} notify={notify}/>}
   {view==='models'&&<ModelsPage data={data} edit={(item?:Item,preset?:string)=>setModal({type:'provider',item,preset})} act={act} refresh={refresh} notify={notify} go={go}/>}
   {view==='runs'&&<RunsPage data={data} select={setSelectedRun} go={go}/>}
   {view==='settings'&&<SettingsPage data={data} act={act} refresh={refresh} notify={notify}/>}
  </main>
  {toast&&<div role="status" className={cx('toast',toast.error&&'error')}>{toast.error?<AlertCircle size={18}/>:<CheckCircle2 size={18}/>}<span>{toast.message}</span><button className="icon-button" aria-label="Dismiss notification" onClick={()=>setToast(null)}><X size={15}/></button></div>}
  {modal?.type==='connector'&&<ConnectorModal item={modal.item} data={data} close={()=>setModal(null)} onSave={(value:Item)=>act('connector',async()=>{await post('/connectors',value);await refresh();setModal(null);notify("Connection saved.");})} busy={busy}/>}
  {modal?.type==='provider'&&<ProviderModal data={data} item={modal.item} preset={modal.preset} close={()=>setModal(null)} onSave={(value:Item)=>act('provider',async()=>{await post('/providers',value);await refresh();setModal(null);notify("Model connection saved.");})} busy={busy}/>}
  {modal?.type==='workflow'&&workflow&&<WorkflowModal workflow={workflow} onDuplicate={duplicateWorkflow} onSaveTemplate={()=>act('template',async()=>{await post('/workflow-templates',{name:workflow.name,workflow:cleanWorkflow(workflow)});await refresh();notify("Saved as a template.");})} close={()=>setModal(null)} onSave={(value:Item)=>act('save',async()=>{await save(value);setModal(null);notify("Workflow settings saved.");})} onExport={()=>{downloadJson(workflow,`${workflow.name}.json`);}} onDelete={()=>act('delete',async()=>{await api('/workflows/'+workflow.id,{method:'DELETE'});localStorage.removeItem('agentflux:draft:'+workflow.id);localStorage.removeItem('agentflux:last-workflow');setWorkflow(null);await refresh();setModal(null);go('overview');})}/>}
  {modal?.type==='assistant'&&<AssistantModal data={data} close={()=>setModal(null)} busy={busy} onGenerate={(value:Item)=>act('assistant',async()=>{const w=await post('/assistant/workflow',value);setWorkflow(w);setModal(null);go('studio');notify("Draft created. Review the steps before running it.");})}/>}
  {modal?.type==='video'&&<Modal wide title="Workflow from a video" description="Let the agent identify visible actions and turn them into an editable workflow." onClose={()=>setModal(null)}><VideoWorkflow data={data} close={()=>setModal(null)} onOpen={(w:Item)=>{setWorkflow(w);setModal(null);go('studio');notify("Video draft opened. Review the steps and save the workflow.");}}/></Modal>}
  {modal?.type==='search'&&<SearchModal data={data} close={()=>setModal(null)} choose={(w:Item)=>{openWorkflow(w);setModal(null);}} go={(v:View)=>{go(v);setModal(null);}}/>}
  {modal?.type==='help'&&<Modal title="Quick start" description="The example workflow uses synthetic data only." onClose={()=>setModal(null)}><div className="guide-list"><div><IconBox icon={FolderOpen} color="blue"/><span><strong>1. Connect your data</strong><p>Use the sample inbox, upload files or connect your own API.</p></span></div><div><IconBox icon={Workflow} color="purple"/><span><strong>2. Edit the workflow</strong><p>Drag steps into the editor. Connect them and configure each step.</p></span></div><div><IconBox icon={Play} color="green"/><span><strong>3. Run and review</strong><p>Each run shows its input data, outputs and any errors.</p></span></div></div><p className="fine-print">The included data is synthetic. AI steps need a model connection. External data transfers stay disabled until approved.</p><Button variant="primary" onClick={()=>{setModal(null);go('studio');}} icon={ArrowRight}>Open editor</Button></Modal>}
  {selectedRun&&<RunDrawer key={selectedRun.id} run={selectedRun} close={()=>setSelectedRun(null)} act={act} notify={notify} select={setSelectedRun}/>}
 </div>;
}

function Logo(){return <span className="logo-mark"><svg viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M7 24 15.5 7 24 24M10.5 18h10" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"/><circle cx="25.5" cy="7.5" r="3" fill="currentColor"/></svg></span>;}

function Overview({data,openWorkflow,go,newWorkflow,assistant}:any){return <div className="page overview-page"><div className="page-heading"><div><div className="hello-line"><span className="status-dot"/>Local AI platform</div><h1>Overview</h1><p>Workflows, data sources and models on your instance.</p></div><Button icon={Plus} variant="primary" onClick={newWorkflow}>New workflow</Button></div>
 <div className="overview-feature"><div className="feature-copy"><span className="feature-label"><Workflow size={15}/> FROM INPUT TO OUTPUT</span><h2>Describe a task.<br/>Let an agent handle the workflow.</h2><p>Agents create workflows, run them on a schedule and save observations for later tasks. You can edit every step.</p><div className="feature-actions"><Button variant="dark" icon={ArrowUpRight} onClick={()=>go('agents')}>Set up an agent</Button><button className="text-button" onClick={assistant}><Sparkles size={15}/>Describe a workflow</button></div><span className="feature-footnote"><LockKeyhole size={12}/>Cloud transfers are {data.settings.allowCloud?"available with approval":"disabled"}</span></div><div className="feature-diagram" aria-label="Files and APIs flow through AgentFlux into knowledge and results"><svg className="diagram-lines" viewBox="0 0 560 300" preserveAspectRatio="none"><path d="M100 78H170Q195 78 195 108V150H280M100 226H170Q195 226 195 198V150H280M300 150H350Q380 150 380 120V78H455M300 150H350Q380 150 380 180V226H455"/></svg><div className="mini-node input-a"><IconBox icon={FolderOpen} color="blue"/><span>Files<small>PDF, CSV, DOCX …</small></span><span className="mini-port"/></div><div className="mini-node input-b"><IconBox icon={Cable} color="orange"/><span>Data sources<small>APIs &amp; programs</small></span><span className="mini-port"/></div><div className="flux-core"><Logo/><span>AgentFlux</span><small>Import and process</small></div><div className="mini-node output-a"><IconBox icon={BrainCircuit} color="purple"/><span>AI model<small>Local or cloud</small></span></div><div className="mini-node output-b"><IconBox icon={Database} color="green"/><span>Knowledge base<small>Stored locally</small></span></div><span className="diagram-caption">LOCAL PROCESSING</span></div></div>
 <div className="overview-stats">{[{label:'Workflows',value:data.stats.workflows,icon:Workflow,go:'studio',detail:"saved workflows"},{label:"Connections",value:data.stats.connectors,icon:Plug,go:'connectors',detail:"configured sources"},{label:"Documents",value:data.stats.records,icon:Database,go:'data',detail:"in the knowledge base"},{label:"Runs",value:data.stats.runs,icon:History,go:'runs',detail:`${data.stats.completed} completed`}].map(s=><button key={s.label} className="stat" onClick={()=>go(s.go)}><div><s.icon size={17}/><span>{s.label}</span><ArrowUpRight size={14}/></div><strong>{s.value.toString().padStart(2,'0')}</strong><small>{s.detail}</small></button>)}</div>
 <div className="overview-lower"><section className="workflow-section"><div className="section-heading"><h2>Workflows <span>{data.workflows.length}</span></h2><button className="text-button" onClick={()=>go('studio')}>Open editor <ArrowRight size={14}/></button></div><div className="workflow-list">{data.workflows.map((w:Item,i:number)=><button className="workflow-row" key={w.id} onClick={()=>openWorkflow(w)}><IconBox icon={i===1?BrainCircuit:i===2?Cable:Workflow} color={i===1?'purple':i===2?'blue':'green'}/><span className="workflow-row-title"><strong>{w.name}</strong><small>{w.description}</small></span><span className="workflow-row-meta">{w.nodes.length} steps<small>{w.schedule?.enabled?"Scheduled":"Manual"}</small></span><ArrowUpRight size={18}/></button>)}</div></section><section className="getting-started"><div className="section-heading"><h2>Getting started</h2><Sparkles size={18}/></div><p>The example workflow runs without a model.</p>{[{label:"Connect your data",detail:"Folders, APIs and programs",icon:Plug,view:'connectors',done:data.connectors.length>3},{label:"Add a model",detail:"Ollama, local or external APIs",icon:BrainCircuit,view:'models',done:data.providers.length>0},{label:"Run your first workflow",detail:"With synthetic sample data",icon:Play,view:'studio',done:data.stats.runs>0}].map(s=><button key={s.view} onClick={()=>go(s.view)} className="onboard-step"><span className={cx('step-check',s.done&&'done')}>{s.done?<Check size={15}/>:<s.icon size={15}/>}</span><span><strong>{s.label}</strong><small>{s.detail}</small></span><ChevronRight size={15}/></button>)}</section></div>
 <div className="page-bottom"><span><Server size={14}/>Data and execution on this instance</span><span>Open Source · Apache 2.0 <ArrowUpRight size={12}/></span></div>
 </div>;}

function FluxNode({data,selected}:NodeProps){const d=data as Item;const kind=kinds[d.kind]||kinds.source;const Icon=kind.icon;return <div className={cx('flow-node',selected&&'selected',d.runStatus&&`run-${d.runStatus}`)}><div className="node-top"><IconBox icon={Icon} color={kind.color}/><span className="node-type">{kind.tag}</span>{d.runStatus==='completed'?<CheckCircle2 className="node-check" size={15}/>:d.runStatus==='running'?<LoaderCircle className="spin" size={15}/>:d.runStatus==='failed'?<AlertCircle className="node-error" size={15}/>:<MoreHorizontal size={16}/>}</div><strong>{d.label}</strong><div className="node-subtitle">{d.subtitle||kind.description}</div><div className="node-bottom"><span className={cx('node-status-dot',kind.color)}/>{d.runStatus==='completed'?`${d.outputCount} records`:d.runStatus==='failed'?"Step failed":d.needsConfig?"Configuration needed":d.kind==='model'&&!d.config?.providerId?"Select model":d.kind==='trigger'?"Manual / scheduled":"Ready"}<span>{d.durationMs!==undefined?duration(d.durationMs):''}</span></div>{d.kind!=='trigger'&&<Handle type="target" position={Position.Left}/>} {d.kind!=='output'&&(d.kind==='condition'?<><Handle type="source" position={Position.Right} id="true" style={{top:'40%'}}/><span className="branch-label yes">Yes</span><Handle type="source" position={Position.Right} id="false" style={{top:'76%'}}/><span className="branch-label no">No</span></>:<Handle type="source" position={Position.Right}/>)}</div>;}
const nodeTypes={flux:FluxNode};
function ComparisonFields({config:c,update}:any){return <><Field label="Field" hint="For example content, title or metadata.priority."><input value={c.field||''} onChange={e=>update({field:e.target.value})}/></Field><Field label="Comparison"><select value={c.operator||'contains'} onChange={e=>update({operator:e.target.value})}><option value="contains">contains</option><option value="not_contains">does not contain</option><option value="equals">equals</option><option value="not_equals">does not equal</option><option value="exists">exists</option><option value="greater">is greater than</option><option value="less">is less than</option></select></Field>{c.operator!=='exists'&&<Field label="Value"><input value={c.value??''} onChange={e=>update({value:e.target.value})}/></Field>}</>;}
function NodeFields({node,data,update}:any){
 const c=node.data.config||{};
 switch(node.data.kind){
 case 'trigger':return <Field label="Initial input" hint="Passed to the first step."><textarea rows={4} value={c.input||''} placeholder="Optional context" onChange={e=>update({input:e.target.value})}/></Field>;
 case 'source':return <><Field label="Source"><select value={c.mode==='library'?'__library':c.mode==='inline'?'__inline':c.connectorId||''} onChange={e=>update(e.target.value==='__library'?{mode:'library',connectorId:''}:e.target.value==='__inline'?{mode:'inline',connectorId:''}:{mode:'connector',connectorId:e.target.value})}><option value="">Select source</option><option value="__inline">Enter text or JSON</option><option value="__library">Search knowledge base</option>{data.connectors.map((source:Item)=><option value={source.id} key={source.id}>{source.name}</option>)}</select></Field>{c.mode==='inline'&&<Field label="Text or JSON" hint="A JSON array creates one record per item."><textarea className="code-input" rows={12} value={c.text||''} onChange={e=>update({text:e.target.value})}/></Field>}{c.mode==='library'&&<><Field label="Search term"><input value={c.query||''} onChange={e=>update({query:e.target.value})}/></Field><Field label="Maximum documents"><input type="number" min="1" max="500" value={c.limit||30} onChange={e=>update({limit:Number(e.target.value)})}/></Field></>}<p className="field-info">Add more folders, APIs and programs under Connections.</p></>;
 case 'transform':return <><Field label="Processing"><select value={c.operation||'clean'} onChange={e=>update({operation:e.target.value,...(['filter','sort'].includes(e.target.value)&&!c.field?{field:'content'}:{})})}><option value="clean">Clean text</option><option value="deduplicate">Remove duplicates</option><option value="filter">Filter records</option><option value="sort">Sort</option><option value="limit">Limit count</option><option value="fields">Map fields</option></select></Field>{c.operation==='filter'&&<ComparisonFields config={c} update={update}/>}{c.operation==='sort'&&<><Field label="Field"><input value={c.field||'title'} onChange={e=>update({field:e.target.value})}/></Field><Field label="Order"><select value={c.direction||'asc'} onChange={e=>update({direction:e.target.value})}><option value="asc">Ascending</option><option value="desc">Descending</option></select></Field></>}{c.operation==='limit'&&<Field label="Count"><input type="number" min="1" max="500" value={c.limit||10} onChange={e=>update({limit:Number(e.target.value)})}/></Field>}{c.operation==='fields'&&<Field label="Field mapping (JSON)" hint='Beispiel: {"title":"title","abteilung":"metadata.department"}'><textarea className="code-input" rows={7} value={typeof c.mapping==='string'?c.mapping:JSON.stringify(c.mapping||{title:'title',text:'content'},null,2)} onChange={e=>update({mapping:e.target.value})}/></Field>}</>;
 case 'condition':return <><ComparisonFields config={c} update={update}/><p className="field-info">Connect Yes and No to their next steps. An unconnected output discards its matching records.</p></>;
 case 'model':return <><Field label="Model"><select value={c.providerId||''} onChange={e=>update({providerId:e.target.value})}><option value="">Select model</option>{data.providers.map((provider:Item)=><option value={provider.id} key={provider.id}>{provider.name} · {provider.scope==='local'?"Local":'Cloud'}</option>)}</select></Field>{!data.providers.length&&<p className="field-info">Add a model server under Models.</p>}<Field label="Task"><textarea rows={8} value={c.prompt||''} onChange={e=>update({prompt:e.target.value})} placeholder="What should the model do with the incoming documents?"/></Field><Field label="Processing"><select value={c.mode||'batch'} onChange={e=>update({mode:e.target.value})}><option value="batch">All documents together</option><option value="per-record">Each document separately (up to 50)</option></select></Field><div className="form-two"><Field label="Temperature"><input type="number" min="0" max="2" step="0.1" value={c.temperature??0.2} onChange={e=>update({temperature:Number(e.target.value)})}/></Field><Field label="Output tokens"><input type="number" min="128" max="16384" step="128" value={c.maxTokens||2048} onChange={e=>update({maxTokens:Number(e.target.value)})}/></Field></div><Field label="Result title"><input value={c.title||''} placeholder="Summary" onChange={e=>update({title:e.target.value})}/></Field></>;
 case 'agent':return <><Field label="Agent"><select value={c.agentId||''} onChange={e=>update({agentId:e.target.value})}><option value="">Select agent</option>{(data.agents||[]).map((agent:Item)=><option key={agent.id} value={agent.id}>{agent.name}</option>)}</select></Field><p className="field-info">Set up agents under Agents. This step processes incoming data using the agent's model and skills.</p><Field label="Task for this step" hint="Leave blank to use the agent's saved task."><textarea rows={8} value={c.prompt||''} onChange={e=>update({prompt:e.target.value})} placeholder="What should the agent do here?"/></Field><Toggle label="Use learnings" description="Include relevant saved observations as context." checked={c.useMemory!==false} onChange={(value:boolean)=>update({useMemory:value})}/><div className="field"><span>Additional skills</span>{(data.skills||[]).filter((skill:Item)=>skill.status==='active').map((skill:Item)=><label className="skill-choice" key={skill.id}><input type="checkbox" checked={(c.skillIds||[]).includes(skill.id)} onChange={e=>update({skillIds:e.target.checked?[...(c.skillIds||[]),skill.id]:(c.skillIds||[]).filter((id:string)=>id!==skill.id)})}/>{skill.name}</label>)}{!data.skills?.length&&<small>No skills yet.</small>}</div></>;
 case 'redact':return <div className="mask-explanation"><ShieldCheck size={23}/><strong>Redact before processing</strong><p>Replaces detected email addresses, Swiss phone numbers, social security numbers, Swiss IBANs and custom terms.</p><small>Add custom terms in Settings. Detection is not exhaustive.</small></div>;
 case 'store':return <div className="field-info with-icon"><Database size={22}/><p>Saves documents locally. Identical content from the same source is not duplicated. The output can connect to further steps.</p></div>;
 default:return <div className="field-info with-icon"><FileText size={22}/><p>Full results are available to download as JSON and CSV in the run details.</p></div>;
 }
}

function DataPage({data,upload,busy,act,notify,refresh}:any){const [records,setRecords]=useState<Item[]>([]);const [query,setQuery]=useState('');const [selected,setSelected]=useState<Item|null>(null);const [drag,setDrag]=useState(false);const input=useRef<HTMLInputElement>(null);const load=()=>api('/records').then(setRecords).catch((e:any)=>notify(e.message,true));useEffect(()=>{load();window.addEventListener('records-changed',load);return()=>window.removeEventListener('records-changed',load);},[data.stats.records]);const visible=records.filter(r=>`${r.title} ${r.content} ${r.source}`.toLowerCase().includes(query.toLowerCase()));return <div className="page"><PageHeading title="Documents and data" description="Imported files, API data and saved workflow results."><Button icon={Upload} variant="primary" onClick={()=>input.current?.click()} disabled={!!busy}>Add files</Button></PageHeading><input ref={input} type="file" multiple hidden accept={data.capabilities.formats.join(',')} onChange={e=>{if(e.target.files?.length)upload(e.target.files);e.target.value='';}}/><div className={cx('upload-zone',drag&&'drag-over')} role="button" tabIndex={0} onClick={()=>input.current?.click()} onKeyDown={e=>{if(e.key==='Enter')input.current?.click();}} onDragOver={e=>{e.preventDefault();setDrag(true);}} onDragLeave={()=>setDrag(false)} onDrop={e=>{e.preventDefault();setDrag(false);if(e.dataTransfer.files.length)upload(e.dataTransfer.files);}}><div className="upload-visual"><FileText size={23}/><span><Plus size={13}/></span></div><div><strong>{busy==='upload'?"Importing files …":"Import files"}</strong><p>Drop files here or <span>browse</span></p><small>PDF, DOCX, XLSX, CSV, JSON, Markdown and text · up to 12 MB per file</small></div><span className="upload-local"><LockKeyhole size={14}/>Stored locally</span></div><div className="table-toolbar"><h2>All documents <span className="count-badge">{records.length}</span></h2><div className="search-field"><Search size={16}/><input placeholder="Search documents …" value={query} onChange={e=>setQuery(e.target.value)}/></div></div>{visible.length?<div className="data-table"><div className="table-head"><span>Document</span><span>Source</span><span>Classification</span><span>Added</span><span/></div>{visible.map(r=><div className="table-row" key={r.id}><button className="document-name" onClick={()=>setSelected(r)}><IconBox icon={FileText} color="blue"/><span><strong>{r.title}</strong><small>{r.content.length.toLocaleString("en-GB")} characters</small></span></button><span className="source-name">{r.source}</span><span><span className="badge">{r.classification==='public'?"Public":r.classification==='sensitive'?"Sensitive":"Internal"}</span></span><span className="table-date">{formatDate(r.createdAt)}</span><button className="icon-button" aria-label={`Delete ${r.title}`} onClick={()=>act('delete',async()=>{await api('/records/'+r.id,{method:'DELETE'});await load();await refresh();})}><Trash2 size={15}/></button></div>)}</div>:<Empty icon={Database} title={query?"No matching documents":"No documents yet"} description={query?"Try another search term.":"Upload files or start with the synthetic sample data."}>{!query&&<Button icon={Inbox} onClick={()=>act('import',async()=>{const result=await post('/connectors/inbox/import');await load();await refresh();notify(`${result.count} sample records imported.`);})}>Import sample data</Button>}</Empty>}{selected&&<Modal title={selected.title} description={`${selected.source} · ${formatDate(selected.createdAt)}`} wide onClose={()=>setSelected(null)}><div className="document-content">{selected.content}</div><Button icon={Download} onClick={()=>downloadJson(selected,selected.title+'.json')}>Export as JSON</Button></Modal>}</div>;}
function PageHeading({title,description,children}:any){return <div className="page-heading"><div><h1>{title}</h1><p>{description}</p></div><div className="heading-actions">{children}</div></div>;}
function ConnectorsPage({data,edit,act,refresh,notify}:any){return <div className="page"><PageHeading title="Data sources" description="Set up folders, APIs, programs and text as reusable sources."><Button icon={Plus} variant="primary" onClick={()=>edit()}>New connection</Button></PageHeading><div className="connector-types">{Object.entries(connectorTypes).map(([type,t])=><button key={type} onClick={()=>edit({type,config:{}})}><IconBox icon={t.icon} color={t.color} size="large"/><strong>{t.label}</strong><span>{t.detail}</span><ArrowUpRight size={17}/></button>)}</div><div className="section-heading spaced"><h2>Configured data sources <span>{data.connectors.length}</span></h2><span className="muted-caption">Reuse across workflows</span></div><div className="connector-list">{data.connectors.map((c:Item)=>{const t=connectorTypes[c.type];return <div className="connector-row" key={c.id}><IconBox icon={t.icon} color={t.color} size="large"/><div className="connector-info"><strong>{c.name}</strong><p>{c.description||t.detail}</p><code>{c.type==='folder'?c.config.path:c.type==='http'?c.config.url:c.type==='program'?c.config.programId:'Text / JSON'}</code></div><div className="connector-badges"><span className="badge">{t.label}</span><small><span className="tiny-dot configured"/>Configured</small></div><div className="row-actions"><Button onClick={()=>act('import',async()=>{const result=await post(`/connectors/${c.id}/import`);await refresh();notify(`${result.count} records imported.`);})} icon={Download}>Import</Button><button className="icon-button" aria-label={`${c.name} bearbeiten`} onClick={()=>edit(c)}><Settings2 size={18}/></button><button className="icon-button" aria-label={`Delete ${c.name}`} onClick={()=>act('delete',async()=>{await api('/connectors/'+c.id,{method:'DELETE'});await refresh();})}><Trash2 size={16}/></button></div></div>;})}</div><div className="integration-note"><div><Terminal size={27}/></div><span><strong>Connect programs without an API</strong><p>Registered programs can provide JSON or text. AgentFlux imports their output like any other source.</p></span><span className="badge">JSON · STDOUT · REST</span></div></div>;}

function ConnectorModal({item,data,close,onSave,busy}:any){const [headerText,setHeaderText]=useState(JSON.stringify(item?.config?.headers||{},null,2));const [formError,setFormError]=useState('');const [form,setForm]=useState<Item>({...{name:'',type:'folder',description:'',config:{path:data.capabilities.inbox}},...item});const update=(p:Item)=>setForm({...form,...p});const config=(p:Item)=>update({config:{...form.config,...p}});return <Modal title={item?.id?"Edit connection":"Add data source"} description="The saved source will be available in the workflow editor." onClose={close}><form onSubmit={e=>{e.preventDefault();try{const value=form.type==='http'?{...form,config:{...form.config,headers:JSON.parse(headerText)}}:form;setFormError('');onSave(value);}catch{setFormError("Additional headers must be a valid JSON object.");}}}><div className="form-two"><Field label="Name"><input required value={form.name} onChange={e=>update({name:e.target.value})} placeholder="e.g. Document archive"/></Field><Field label="Type"><select value={form.type} onChange={e=>update({type:e.target.value,config:{}})}>{Object.entries(connectorTypes).map(([key,t])=><option key={key} value={key}>{t.label}</option>)}</select></Field></div><Field label="Description"><input value={form.description||''} onChange={e=>update({description:e.target.value})} placeholder="What does your team use this source for?"/></Field>{form.type==='folder'&&<Field label="Folder path on the server" hint="The local inbox is allowed. Add other paths with AGENTFLUX_IMPORT_ROOTS."><input required value={form.config.path||''} onChange={e=>config({path:e.target.value})} placeholder={data.capabilities.inbox}/></Field>}{form.type==='http'&&<><div className="form-two url-form"><Field label="Method"><select value={form.config.method||'GET'} onChange={e=>config({method:e.target.value})}><option>GET</option><option>POST</option></select></Field><Field label="API URL"><input type="url" required value={form.config.url||''} onChange={e=>config({url:e.target.value})} placeholder="http://localhost:8080/api/records"/></Field></div><Field label="Bearer token (optional)" hint={form.hasSecret?"Credentials are saved. Leave blank to keep them.":"Stored encrypted on your local instance."}><input type="password" autoComplete="new-password" value={form.secret||''} onChange={e=>update({secret:e.target.value||undefined})} placeholder={form.hasSecret?'••••••••':"Enter token"}/></Field><Field label="Additional headers (JSON)" hint='Beispiel: {"X-Tenant":"team-a"}'><textarea rows={3} value={headerText} onChange={e=>setHeaderText(e.target.value)}/></Field><Field label="Path to records" hint="Optional, e.g. data.items. Leave blank to import the entire response."><input value={form.config.responsePath||''} onChange={e=>config({responsePath:e.target.value})} placeholder="data.items"/></Field><p className="field-info">POST receives incoming workflow records. External transfers require approval.</p></>}{form.type==='program'&&<><Field label="Allowed program"><select required value={form.config.programId||''} onChange={e=>config({programId:e.target.value})}><option value="">Select program</option>{data.capabilities.programs.map((p:Item)=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><p className="field-info">Register programs in data/programs.json with a fixed executable and arguments. Enable execution in Settings.</p></>}{form.type==='text'&&<Field label="Content"><textarea required rows={7} value={form.config.text||''} onChange={e=>config({text:e.target.value})} placeholder='Text oder [{"title":"Mein Dokument","content":"…"}]'/></Field>}<div className="modal-actions"><Button type="button" onClick={close}>Cancel</Button><Button type="submit" variant="primary" icon={Check} disabled={!!busy}>Save connection</Button></div>{formError&&<p role="alert" className="step-error">{formError}</p>}</form></Modal>;}

function ModelsPage({data,edit,act,refresh,notify,go}:any){return <div className="page"><PageHeading title="Models" description="Connect a local model server or an external API."><Button variant="primary" icon={Plus} onClick={()=>edit()}>Connect model</Button></PageHeading><div className="model-intro"><div className="model-intro-copy"><span className="mini-label"><BrainCircuit size={16}/> Model connections</span><h2>Local and external models<br/>in the same workflow.</h2><p>Each AI step uses your selected connection. Supports Ollama and OpenAI-compatible chat APIs.</p><div className="model-protocols"><span>Ollama</span><span>LM Studio</span><span>vLLM</span><span>OpenAI-compatible</span></div></div><div className="model-art"><div className="model-orbit outer"/><div className="model-orbit inner"/><div className="model-art-center"><BrainCircuit size={45} strokeWidth={1.1}/></div><span className="orbit-tag local"><Server size={15}/>Local</span><span className="orbit-tag cloud"><Globe2 size={15}/>Cloud</span><span className="model-art-dot a"/><span className="model-art-dot b"/></div></div><div className="section-heading spaced"><h2>Connected models <span>{data.providers.length}</span></h2><button className="text-button" onClick={()=>go('settings')}><ShieldCheck size={15}/>Manage data permissions</button></div>{data.providers.length?<div className="provider-list">{data.providers.map((p:Item)=><div className="provider-row" key={p.id}><IconBox icon={p.scope==='local'?Server:Globe2} color={p.scope==='local'?'green':'purple'} size="large"/><div><strong>{p.name}</strong><p>{p.model}</p><code>{p.baseUrl}</code></div><span className={cx('badge',p.scope==='local'&&'green')}>{p.scope==='local'?"Local":'Cloud'}</span><div className="row-actions"><Button icon={RefreshCw} onClick={()=>act('discover',async()=>{const result=await post(`/providers/${p.id}/discover`);notify(`${result.models.length} models available: ${result.models.slice(0,3).join(', ')}`);})}>List models</Button><button className="icon-button" aria-label="Edit model" onClick={()=>edit(p)}><Settings2 size={18}/></button><button className="icon-button" aria-label="Remove model" onClick={()=>act('delete',async()=>{await api('/providers/'+p.id,{method:'DELETE'});await refresh();})}><Trash2 size={16}/></button></div></div>)}</div>:<div className="model-choices"><button onClick={()=>edit(undefined,'ollama')}><IconBox icon={Server} color="green" size="large"/><div><h3>A local model</h3><p>Connect Ollama or your local model server.</p><span>Set up local server <ArrowRight size={15}/></span></div><span className="choice-badge">LOCAL</span></button><button onClick={()=>edit(undefined,'cloud')}><IconBox icon={Globe2} color="purple" size="large"/><div><h3>An external model</h3><p>Connect an external API. Data transfers require separate approval.</p><span>Connect API <ArrowRight size={15}/></span></div></button></div>}<div className="privacy-strip"><ShieldCheck size={21}/><p><strong>Cloud transfers are blocked by default.</strong> Cloud calls need global and per-workflow approval. Redaction can remove detected information but does not guarantee anonymisation.</p></div></div>;}
function ProviderModal({data,item,preset,close,onSave,busy}:any){const [form,setForm]=useState<Item>({...{name:'',type:preset==='cloud'?'openai':'ollama',scope:preset==='cloud'?'cloud':'local',baseUrl:preset==='cloud'?'':data.capabilities.modelDefaults?.ollama||'http://127.0.0.1:11434',model:''},...item});const update=(p:Item)=>setForm({...form,...p});return <Modal title={item?"Edit model":"Add model"} description="Enter your server or provider's address and model ID." onClose={close}><form onSubmit={e=>{e.preventDefault();onSave(form);}}>{!item&&<Field label="Server preset"><select defaultValue="" onChange={e=>{const host=data.capabilities.container?'host.docker.internal':'127.0.0.1';const presets:Record<string,Item>={ollama:{name:'Ollama',type:'ollama',scope:'local',baseUrl:`http://${host}:11434`},lmstudio:{name:'LM Studio',type:'openai',scope:'local',baseUrl:`http://${host}:1234/v1`},vllm:{name:'vLLM',type:'openai',scope:'local',baseUrl:`http://${host}:8000/v1`},external:{name:"External model server",type:'openai',scope:'cloud',baseUrl:''}};if(presets[e.target.value])update(presets[e.target.value]);}}><option value="">Choose preset</option><option value="ollama">Ollama</option><option value="lmstudio">LM Studio</option><option value="vllm">vLLM</option><option value="external">External compatible API</option></select></Field>}<Field label="Display name"><input required value={form.name} onChange={e=>update({name:e.target.value})} placeholder="e.g. Local model server"/></Field><div className="form-two"><Field label="Protocol"><select value={form.type} onChange={e=>update({type:e.target.value,baseUrl:e.target.value==='ollama'?(data.capabilities.modelDefaults?.ollama||'http://127.0.0.1:11434'):(data.capabilities.modelDefaults?.openai||'http://127.0.0.1:1234/v1')})}><option value="ollama">Ollama</option><option value="openai">OpenAI-compatible API</option></select></Field><Field label="Connection type"><select value={form.scope} onChange={e=>update({scope:e.target.value})}><option value="local">Local network</option><option value="cloud">External cloud</option></select></Field></div><Field label="Base URL" hint={form.type==='ollama'?"Without /api/chat. In Docker, use host.docker.internal if needed.":"Include the API prefix, e.g. http://localhost:1234/v1. Without /chat/completions."}><input required type="url" value={form.baseUrl} onChange={e=>update({baseUrl:e.target.value})} placeholder="https://dein-anbieter.example/v1"/></Field><Field label="Model ID" hint="The exact model name on your server or with your provider."><input required value={form.model} onChange={e=>update({model:e.target.value})} placeholder="Enter model ID"/></Field><Field label="API key (optional)" hint={item?.hasKey?"A key is saved. Leave blank to keep it.":"Encrypted locally. Never returned to the browser."}><input type="password" autoComplete="new-password" value={form.apiKey||''} onChange={e=>update({apiKey:e.target.value||undefined})}/></Field>{form.scope==='cloud'&&<div className="field-info">External calls remain blocked until approved in Settings and in the workflow.</div>}<div className="modal-actions"><Button type="button" onClick={close}>Cancel</Button><Button variant="primary" type="submit" disabled={!!busy} icon={Plug}>Connect model</Button></div></form></Modal>;}

function RunsPage({data,select,go}:any){return <div className="page"><PageHeading title="Runs" description="Executions, results and errors from your workflows."/>{data.runs.length?<div className="runs-list"><div className="run-table-head"><span>Workflow</span><span>Status</span><span>Trigger</span><span>Duration</span><span>Start</span><span/></div>{data.runs.map((run:Item)=><button className="run-table-row" key={run.id} onClick={()=>select(run)}><span className="run-title"><IconBox icon={Workflow} color="green"/><strong>{run.workflowName}</strong></span><Status status={run.status}/><span>{run.trigger==='schedule'?"Schedule":run.trigger==='agent'?'Agent':"Manual"}</span><span>{run.durationMs!==undefined?duration(run.durationMs):"Running …"}</span><span>{formatDate(run.startedAt)}</span><ChevronRight size={17}/></button>)}</div>:<Empty icon={History} title="No runs yet" description="Start a workflow to see its steps and results here."><Button variant="primary" icon={Play} onClick={()=>go('studio')}>Open workflow editor</Button></Empty>}<div className="privacy-strip"><Clock3 size={20}/><p>History is stored locally. Retention: <strong>{data.settings.retentionDays} days.</strong> The preview includes up to three documents per step.</p></div></div>;}
function Status({status}:any){return <span className={cx('status-badge',status)}>{status==='running'?<LoaderCircle size={13} className="spin"/>:status==='completed'?<CheckCircle2 size={13}/>:status==='failed'?<AlertCircle size={13}/>:<Circle size={13}/>}{{running:"Running",completed:"Completed",failed:"Failed",skipped:"Skipped",cancelled:"Cancelled"}[status as string]||status}</span>;}
function RunDrawer({run,close,act,notify,select}:any){
 const [open,setOpen]=useState<string|null>(null);const [result,setResult]=useState<Item[]|null>(null);const [resultError,setResultError]=useState('');const [resultInfo,setResultInfo]=useState({truncated:false,totalCount:0});
 useEffect(()=>{let active=true;setResult(null);setResultError('');if(run.status!=='running')api('/runs/'+run.id+'/result').then(value=>{if(active){setResult(value.records||[]);setResultInfo({truncated:value.truncated===true,totalCount:value.totalCount??value.records?.length??0});}}).catch(error=>{if(active)setResultError(error.message);});return()=>{active=false;};},[run.id,run.status]);
 useEffect(()=>{const key=(e:KeyboardEvent)=>{if(e.key==='Escape')close();};window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key);},[close]);
 return <div className="drawer-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close();}}><aside className="run-drawer" role="dialog" aria-modal="true" aria-label="View run"><div className="drawer-top"><span><History size={18}/>Run</span><button className="icon-button" aria-label="Close" onClick={close}><X size={20}/></button></div><h2>{run.workflowName}</h2><div className="run-summary"><Status status={run.status}/><span>{formatDate(run.startedAt)}</span>{run.durationMs!==undefined&&<span>{duration(run.durationMs)}</span>}</div>{run.error&&<div className="error-banner"><AlertCircle size={18}/>{run.error}</div>}<div className="run-actions">{run.status==='running'?<Button variant="danger" onClick={()=>act('cancel',async()=>{await post('/runs/'+run.id+'/cancel');notify("Cancellation requested. Completed writes are kept.");})}>Cancel run</Button>:<Button icon={Play} onClick={()=>act('retry',async()=>{const next=await post('/runs/'+run.id+'/retry');select(next);notify("New run started with the saved settings.");})}>Run again</Button>}<Button icon={Download} onClick={()=>downloadJson(run,`agentflux-verlauf-${run.id}.json`)}>Export history</Button></div><div className="run-step-list">{run.steps.map((step:Item)=>{const kind=kinds[step.kind]||kinds.source;return <div className="run-step" key={step.nodeId}><button onClick={()=>setOpen(open===step.nodeId?null:step.nodeId)}><IconBox icon={kind.icon} color={kind.color}/><span><strong>{step.label}</strong><small>{step.inputCount} in · {step.outputCount} out · {duration(step.durationMs)}</small></span><Status status={step.status}/><ChevronDown size={16}/></button>{step.detail&&<div className="step-detail">{step.detail}</div>}{step.error&&<div className="step-error">{step.error}</div>}{open===step.nodeId&&<div className="step-previews">{step.preview?.length?step.preview.map((preview:Item,i:number)=><div key={i}><strong>{preview.title}</strong><pre>{preview.content}</pre><small>{preview.source}</small></div>):<p>No output for this step.</p>}</div>}</div>;})}</div>{run.status!=='running'&&<section className="run-results"><h3>{resultInfo.truncated?"Limited result output":"Full results"}</h3>{resultError?<p className="step-error">{resultError}</p>:result===null?<p>Loading results.</p>:<><p>{resultInfo.truncated?`${result.length} of ${resultInfo.totalCount} records saved. Downloads contain this selection. Limit the input or split the workflow.`:`${result.length} records from the final steps.`} {run.recordCount||0} saved to the knowledge base.</p><div className="run-actions"><Button icon={Download} disabled={!result.length} onClick={()=>downloadJson(result,`agentflux-ergebnisse-${run.id}.json`)}>Download JSON</Button><Button icon={Download} disabled={!result.length} onClick={()=>downloadCsv(result,`agentflux-ergebnisse-${run.id}.csv`)}>Download CSV</Button></div>{result.slice(0,10).map((record,index)=><details key={index}><summary>{record.title}</summary><pre>{record.content}</pre><small>{record.source}</small></details>)}{result.length>10&&<p>Downloads contain {result.length} saved records.</p>}</>}</section>}</aside></div>;
}

function TemplatePage({data,choose,create,importFile,assistant,act,refresh}:any){
 const [query,setQuery]=useState('');const input=useRef<HTMLInputElement>(null);const templates=(data.templates||[]).filter((t:Item)=>`${t.name} ${t.description}`.toLowerCase().includes(query.toLowerCase()));
 return <div className="page templates-page"><PageHeading title="Start workflow" description="Describe a task, choose a template or start with an empty canvas."><Button icon={Upload} onClick={()=>input.current?.click()}>Import JSON</Button><Button icon={Plus} onClick={create}>Start blank</Button></PageHeading><input hidden type="file" accept=".json,application/json" ref={input} onChange={e=>{if(e.target.files?.[0])importFile(e.target.files[0]);e.target.value='';}}/><div className="workflow-prompt-entry"><div><Sparkles size={25}/><h2>What needs doing?</h2><p>Describe your source, processing and desired result. Your model will draft an editable workflow.</p></div><Button icon={ArrowRight} variant="primary" onClick={assistant}>Describe task</Button></div><div className="table-toolbar"><h2>Templates <span className="count-badge">{templates.length}</span></h2><div className="search-field"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search templates"/></div></div><div className="template-list">{templates.map((template:Item)=><article className="template-row" key={template.id}><IconBox icon={template.requiresModel?BrainCircuit:Workflow} color={template.requiresModel?'purple':'green'} size="large"/><div><span className="badge">{template.category}</span><h3>{template.name}</h3><p>{template.description}</p><small>{template.workflow.nodes.length} steps · {template.requiresModel?"Model connection required":template.category==="No model needed"?"Ready to use":"Choose source in editor"}</small></div><Button icon={ArrowRight} onClick={()=>choose(template)}>Use template</Button>{template.category==="Custom templates"&&<button className="icon-button" aria-label="Remove template" onClick={()=>act('delete-template',async()=>{await api('/workflow-templates/'+template.id,{method:'DELETE'});await refresh();})}><Trash2 size={16}/></button>}</article>)}</div>{!templates.length&&<Empty icon={BookOpen} title="No matching template" description="Try another search term or create a workflow."/>}</div>;
}

function SettingsPage({data,act,refresh,notify}:any){const [form,setForm]=useState<Item>(data.settings);const update=(p:Item)=>setForm({...form,...p});return <div className="page settings-page"><PageHeading title="Settings" description="Choose how data is processed and which connections are allowed."><Button variant="primary" icon={Save} onClick={()=>act('settings',async()=>{await post('/settings',form);await refresh();notify("Settings saved.");})}>Save changes</Button></PageHeading><div className="settings-layout"><div><section className="settings-section"><div className="settings-section-title"><IconBox icon={ShieldCheck} color="green"/><div><h2>Data and privacy</h2><p>Explicit approval for external processing.</p></div></div><Toggle checked={form.allowCloud} onChange={(v:boolean)=>update({allowCloud:v})} label="Allow external data transfers" description="Each workflow also needs its own approval for cloud models and external POST requests."/><Toggle checked={form.redactCloud} onChange={(v:boolean)=>update({redactCloud:v})} label="Redact before cloud calls" description="Replaces detected email addresses, Swiss phone numbers, social security numbers, IBANs and custom terms."/><Field label="Redact custom terms" hint="One term per line, e.g. names, customer numbers or internal project names."><textarea rows={5} value={(form.redactionTerms||[]).join('\n')} onChange={e=>update({redactionTerms:e.target.value.split('\n')})} placeholder="Internal project name&#10;Person's name"/></Field></section><section className="settings-section"><div className="settings-section-title"><IconBox icon={Terminal} color="orange"/><div><h2>Local programs</h2><p>Use existing applications as data sources.</p></div></div><Toggle checked={form.programsEnabled} onChange={(v:boolean)=>update({programsEnabled:v})} label="Run registered programs" description="Only entries in data/programs.json. Fixed arguments, no shell, 30-second timeout."/></section><section className="settings-section"><div className="settings-section-title"><IconBox icon={History} color="blue"/><div><h2>Retention</h2><p>History stays on this instance.</p></div></div><Field label="Keep runs for (days)" hint="Knowledge base documents are managed separately and are not deleted automatically."><input type="number" min="1" max="365" value={form.retentionDays} onChange={e=>update({retentionDays:Number(e.target.value)})}/></Field></section></div><aside className="settings-aside"><div className="security-illustration"><LockKeyhole size={38} strokeWidth={1.2}/></div><h3>Local storage</h3><p>Workflows, documents and history are stored in the local SQLite database. API keys are encrypted on the same instance.</p><div className="aside-facts"><span>Default deployment<strong>Localhost</strong></span><span>Database<strong>SQLite</strong></span><span>API keys<strong>AES-256-GCM</strong></span><span>Licence<strong>Apache 2.0</strong></span></div><p className="fine-print">This is a single-user instance. Redaction does not guarantee anonymisation. Review external providers and their data handling before using business data.</p></aside></div></div>;}
function WorkflowModal({workflow,close,onSave,onExport,onDelete,onDuplicate,onSaveTemplate}:any){const [form,setForm]=useState<Item>(structuredClone(workflow));return <Modal title="Workflow settings" onClose={close}><form onSubmit={e=>{e.preventDefault();onSave(form);}}><Field label="Name"><input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></Field><Field label="Description"><textarea rows={2} value={form.description||''} onChange={e=>setForm({...form,description:e.target.value})}/></Field><Toggle label="Allow cloud processing" description="Global approval in Settings is also required." checked={form.policy?.allowCloud} onChange={(value:boolean)=>setForm({...form,policy:{...form.policy,allowCloud:value}})}/><Toggle label="Redact before cloud calls" checked={form.policy?.redactCloud!==false} onChange={(value:boolean)=>setForm({...form,policy:{...form.policy,redactCloud:value}})}/><Toggle label="Run automatically" description="Only runs while AgentFlux is active. Program and POST sources require a manual start." checked={form.schedule?.enabled} onChange={(value:boolean)=>setForm({...form,schedule:{...form.schedule,enabled:value}})}/>{form.schedule?.enabled&&<Field label="Interval (minutes)"><input type="number" min="1" required value={form.schedule.intervalMinutes||60} onChange={e=>setForm({...form,schedule:{...form.schedule,intervalMinutes:Number(e.target.value)}})}/></Field>}<div className="workflow-modal-tools"><Button type="button" icon={Copy} onClick={onDuplicate}>Duplicate</Button><Button type="button" icon={BookOpen} onClick={onSaveTemplate}>Save as template</Button><Button type="button" icon={Download} onClick={onExport}>Export JSON</Button><Button type="button" variant="danger" icon={Trash2} onClick={onDelete}>Delete</Button></div><div className="modal-actions"><Button type="button" onClick={close}>Cancel</Button><Button type="submit" variant="primary" icon={Save}>Save</Button></div></form></Modal>;}
function AssistantModal({data,close,onGenerate,busy}:any){const [prompt,setPrompt]=useState('');const [providerId,setProviderId]=useState(data.providers[0]?.id||'');const [allowCloud,setAllowCloud]=useState(false);return <Modal title="Draft a workflow with AI" description="The selected model creates a draft you can edit." onClose={close}><div className="assistant-symbol"><Sparkles size={27}/></div><form onSubmit={e=>{e.preventDefault();onGenerate({prompt,providerId,allowCloud});}}><Field label="What should the workflow do?"><textarea required minLength={5} maxLength={4000} rows={5} value={prompt} onChange={e=>setPrompt(e.target.value)} placeholder="Read files from my inbox, redact personal information and save a summary …"/></Field><div className="suggestion-pills">{["Import and clean data","Filter important records","Summarise documents"].map(p=><button type="button" key={p} onClick={()=>setPrompt(p)}>{p}<ArrowUpRight size={12}/></button>)}</div><Field label="Model for the draft"><select required value={providerId} onChange={e=>setProviderId(e.target.value)}><option value="">Select model</option>{data.providers.map((p:Item)=><option key={p.id} value={p.id}>{p.name} · {p.scope==='local'?"Local":'Cloud'}</option>)}</select></Field>{!data.providers.length&&<p className="field-info">Connect your model server under Models first. It will be called to create the draft.</p>}{data.providers.find((p:Item)=>p.id===providerId)?.scope==='cloud'&&<Toggle checked={allowCloud} onChange={setAllowCloud} label="Send description to this cloud model" description="Sends your task and the names and types of your connections. No stored documents."/>}<div className="modal-actions"><Button type="button" onClick={close}>Cancel</Button><Button type="submit" variant="primary" disabled={!!busy||!providerId} icon={busy==='assistant'?LoaderCircle:Sparkles}>{busy==='assistant'?"Creating draft …":"Draft workflow"}</Button></div></form></Modal>;}
function SearchModal({data,close,choose,go}:any){const [q,setQ]=useState('');return <Modal title="Search AgentFlux" onClose={close}><div className="search-field large"><Search size={20}/><input autoFocus value={q} onChange={e=>setQ(e.target.value)} placeholder="Search workflows and sections …"/></div><div className="search-results">{data.workflows.filter((w:Item)=>w.name.toLowerCase().includes(q.toLowerCase())).map((w:Item)=><button key={w.id} onClick={()=>choose(w)}><Workflow size={17}/><span>{w.name}<small>Workflow · {w.nodes.length} steps</small></span><ArrowUpRight size={16}/></button>)}{nav.filter(n=>n.label.toLowerCase().includes(q.toLowerCase())).map(n=><button key={n.id} onClick={()=>go(n.id)}><n.icon size={17}/><span>{n.label}</span><ChevronRight size={16}/></button>)}</div></Modal>;}
function downloadJson(value:unknown,name:string){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

function downloadCsv(records:Item[],name:string){const escape=(value:any)=>{let text=String(value??'');if(/^[=+@\-]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"';};const rows=[["Title","Content","Source"],...records.map(r=>[r.title,r.content,r.source])];const url=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(row=>row.map(escape).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
